<script setup lang="ts">
import { ref } from 'vue'; import { useRoute } from 'vue-router'; import { showToast } from 'vant'; import { createApiClient } from '../api/client'; import { createIdempotencyKey } from '../api/idempotency'; import RideFallback from '../components/RideFallback.vue'
const route=useRoute(); const client=createApiClient(); const tripId=String(route.params.id); const plate=ref(''); const model=ref(''); const color=ref(''); const saved=ref(false); const busy=ref(false); const error=ref(''); const launchMessage=ref('')
async function save(){if(!plate.value.trim())return;busy.value=true;error.value='';try{await client.updateVehicle(tripId,{plate:plate.value.trim(),model:model.value.trim()||undefined,color:color.value.trim()||undefined},createIdempotencyKey());saved.value=true;showToast('车辆信息已保存')}catch(caught){error.value=caught instanceof Error?caught.message:'保存失败'}finally{busy.value=false}}
async function openRide(){busy.value=true;error.value='';try{const result=await client.openRide(tripId,'manual',createIdempotencyKey());launchMessage.value=result.launch.supported?'已打开叫车平台':'平台暂未接入，请复制路线后手动叫车'}catch(caught){error.value=caught instanceof Error?caught.message:'叫车失败'}finally{busy.value=false}}
</script>
<template><main class="page"><div class="eyebrow">出行准备</div><h1>车辆信息</h1><div class="detail-card"><p>车辆信息仅用于同行识别；叫车平台当前支持手动降级。</p><label>车牌号<input v-model="plate" required placeholder="粤A·12345" /></label><label>车型（可选）<input v-model="model" /></label><label>颜色（可选）<input v-model="color" /></label><button class="primary-button" :disabled="busy || !plate.trim()" @click="save">{{saved?'已保存':'保存车辆信息'}}</button><button class="secondary-button" :disabled="busy" @click="openRide">发起叫车</button><p v-if="launchMessage" class="muted" role="status">{{ launchMessage }}</p><p v-if="error" class="form-error" role="alert">{{ error }}</p></div><RideFallback text="请在行程详情复制出发地和目的地后，手动打开叫车平台。" /></main></template>
